def find_ways(n, population):
    MOD = 10**9 + 7
    dp = [[0] * 26 for _ in range(n+1)]

    for i in range(1, n+1):
        if i == 1:
            dp[i][ord(population[i-1]) - ord('a')] += 1
        else:
            dp[i][ord(population[i-1]) - ord('a')] = 2 * dp[i-1][ord(population[i-1-1]) - ord('a')] % MOD
        if i < n:
            dp[i][ord(population[i+1]) - ord('a')] = 2 * dp[i-1][ord(population[i+1-1]) - ord('a')] % MOD

    return sum(dp[n]) % MOD

