from typing import List, Tuple

def max_weight_subgraph(n: int, m: int, vertices: List[int], edges: List[Tuple[int, int, int]]) -> int:
    vertex_weights_sum = sum(vertices)
    edge_weights_sum = sum(v for _, _, v in edges)

    if n == 1:
        return edge_weights_sum  # A subgraph with a single vertex is just the weight of that vertex.

    # Calculate the potential contributions from each vertex if it were the only vertex in the subgraph.
    vertex_potential = [0] * (n + 1)
    for u, v, w in edges:
        vertex_potential[u] += vertex_weights_sum
        vertex_potential[v] += vertex_weights_sum

    # Sort vertices by their potential contributions to help finding the max subgraph weight efficiently.
    sorted_vertices = sorted(range(n + 1), key=lambda v: vertex_potential[v] - vertices[v])

    # Initialize the weights for the set (base case for single edges or vertex)
    dp = [False] * (1 << n)
    dp[0] = True

    for edges_mask in range(1 << n):
        if dp[edges_mask]:
            if edges_mask > 2 ** (n - 1) - 1:
                break
            for i in sorted_vertices:
                if edges_mask & (1 << i):
                    next_edges_mask = edges_mask | (1 << i)
                    sum_weight = 0
                    for u, v, w in edges:
                        if u == i or v == i:
                            sum_weight += (vertex_weights_sum - vertices[i])
                    dp[next_edges_mask] = True
                    for j in sorted_vertices:
                        if edges_mask & (1 << j):
                            candidate_weight = sum_weight - vertices[j]
                            if edges_mask | (1 << j) < 2 ** (n - 1) - 1:
                                dp[edges_mask | (1 << j)] = max(dp[edges_mask | (1 << j)], candidate_weight)

    return 0 if dp[-1] else max([dp[sum(i) & (1 << edges_mask)] := sum(vertex_weights_sum - vertices[i] for i, bits in enumerate(sorted_vertices) if bits & edges_mask) for edges_mask in range(1 << n)])

