def get_chocades(bracket_sequence, n):
    number_partitions = defaultdict(list)
    for i in range(n * 2):
        a, b = bracket_sequence[i * 2], bracket_sequence[i * 2 + 1]
        number_partitions[abs(a)].append(b)
