    consecutive_values = [sorted_number_partitions[0][1]]
    for number, successor in sorted_number_partitions[1:]:
        if number + 1 == successor[0]:
            consecutive_values.append(successor[-1])
        else:
            break
    return consecutive_values

def is_balanced(bracket_sequence):
    n = len(bracket_sequence)
    while any(abs(a) % 2 != 1 for a in bracket_sequence):
        next_numbers = get_chocades(bracket_sequence, n)
        first_n = next_numbers[:n//2]
        second_n = next_numbers[n//2:]
        for first, second in zip(first_n, second_n):
            if len(next_numbers) % 2 == 0:
                if first < '0' or second > '0':
                    return False
            else:
                if first <= '0' <= second:
                    return False
    return True

