    stack = []
    for card in seq:
        if len(stack) > 0:
            if card == stack[-1]:
                new_stack = stack.pop() + [stack[-1]]
                stack += new_stack
            else:
                stack.append(card)
        else:
            stack.append(card)
    return stack

