def distance(x1, y1, x2, y2):
    return math.sqrt((x1-x2)**2 + (y1-y2)**2)

def normalize_segment(segment):
    x1, y1, x2, y2 = segment
    dx = x2 - x1
    dy = y2 - y1
    d = dx * dx + dy * dy
    if d == 0:
        return segment
    x1 /= d
    y1 /= d
    x2 /= d
    y2 /= d
    return x1, y1, x2, y2

def find_intersection(circle1, circle2):
