from itertools import accumulate

def count_valid_arrays(n, k, m, conditions):
    MOD = 998244353
    range_counts = [0 for _ in range((1 << k) + 1)]
    for l, r, x in conditions:
        binary_representation = bin(x)[2:]
        for i in range(len(binary_representation) - 1, -1, -1):
            count = accumulate(range_counts, xor, initial=1)
            range_counts[((int(binary_representation, 2) << i) | l, int(binary_representation, 2) + (i + 1)) % ((1 << k) + 1)] = count[((int(binary_representation, 2) << i) | l, int(binary_representation, 2) + (i + 1)) % ((1 << k) + 1)] + 1
    return pow((1 << k) - range_counts[(0, 0)], n - m, MOD)

def xor(a, b):
    if a == 0:
        return b
    if b == 0:
        return a
    if a & 1 == 0 and b & 1 == 0:
        return xor(a >> 1, b >> 1) << 1
    else:
        return 1 - xor(a >> 1, b >> 1) - 1

