def count_configurations(sequence):
    modulo = 10**9 + 7
    configurations = 0
    sequence_count = [0] * 50
    sequences = []

    # Count the frequency of each character in the initial sequence
    for char in sequence:
        sequence_count[ord(char) - ord('a') + 1] += 1

    # Simulate all possible transitions
    for _ in range(sequence_count[0]):
        configurations = (configurations << 1) % modulo
        if sequence_count[0] % 2 == 1:
            configurations += 1
            sequence_count[0] -= 2
            configurations %= modulo

        sequences.append(max(0, sequence_count[0]))

    sequences = max(sequences)
    if sequences + 1 > 50:
        return configurations % modulo
    else:
        unique_configurations = num_combinations(sequences)
        unique_configurations = unique_configurations % modulo
        return (configs ** (unique_configurations - 1)) % modulo

def num_combinations(k):
    if k == 0 or k == 1:
        return 1
    else:
        return num_combinations(k - 1) * k % (10**9 + 7)

