def is_symmetrical(circle, segment):
    # Check if the circle is symmetrical to the segment
    center = (circle[0] + circle[2] // 2, circle[1] + circle[3] // 2)
    return center in segment

def count_owls(n, m, segments, circles):
    owls = set()
    for segment in segments:
        for circle1 in circles:
            for circle2 in circles:
                if circle1 == circle2 or circle1[2] > circle2[2]:
                    continue
                center1 = (circle1[0] + circle1[2] // 2, circle1[1] + circle1[3] // 2)
                center2 = (circle2[0] + circle2[2] // 2, circle2[1] + circle2[3] // 2)
                norm = abs(center1[0] - center2[0]) ** 2 + abs(center1[1] - center2[1]) ** 2
                radius1 = max(circle1[2] // 20, 1)
                radius2 = max(circle2[2] // 20, 1)
                zero_dot_product = (center1[0] - center2[0]) * (center1[0] - segment[0]) + \
                                    (center1[1] - center2[1]) * (center1[1] - segment[1])
                if (norm < 2 * (radius1 + radius2) ** 2) and zero_dot_product == 0:
                    if is_symmetrical(circle1, segment) and is_symmetrical(circle2, segment):
                        if circle1 == circle2:
                            owls.add(tuple(sorted((circle1, segment))))
                        else:
                            owls.add(tuple(sorted((circle1, circle2))))
    return len(owls)

