def longest_subarray(n, nums):
    # Dictionary to count occurrences of each element
    freq = {}

    # Find the maximum frequency
    max_freq = max(nums.count(i) for i in range(1, n + 1))

    # If all elements occur no more than twice, return the length of the array
    if max_freq <= 2:
        return n

    frequent_elements = []

    # Count the frequency of each element and identify frequent elements
    for i in range(1, n + 1):
        if (num := nums.count(i)) == max_freq:
            frequent_elements.append(i)

    # If there are no frequent elements, return 0
    if not frequent_elements:
        return 0

    max_length = 0

    # Iterate through possible maximum frequency to find the longest subarray
    for freq in range(2, max_freq + 1):
        for start in range(n - freq + 1):
            end = start + freq
            if (len(frequent_elements) - frequent_elements.count(nums[start:end])) < len(frequent_elements) * 2:
                continue
            max_length = max(max_length, end - start)

    return n - max_length

