import sys

def min_operations_to_red_blue_tree(n, graph, initial_colors):
    red_blue = {}

    def dfs(vertex, color):
        if vertex in red_blue:
            return
        red_blue[vertex] = color

        for neighbor in graph[vertex]:
            if red_blue[neighbor] != color:
                dfs(neighbor, color ^ 1)

    colors_transferred = 0
    minimum_operations = sys.maxsize

    def dfs_with_operations(vertex):
        nonlocal colors_transferred, minimum_operations
        for child in graph[vertex]:
            dfs_with_operations(child)

        if colors_transferred < minimum_operations:
            minimum_operations = colors_transferred

    for color in range(2):
        dfs(1, color)
        dfs_with_operations(1)

    if colors_transferred == n:
        return -1
    else:
        return minimum_operations

