def max_anagrams(n, pattern):
    p = defaultdict(int)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        p[pattern[i]] = i + 1

    def count(sub, level):
        idx = p[sub[level]] - level
        dp[level + 1][idx] = sub[idx], idx
        for i in range(idx + 1, level + 1):
            back = dp[level][idx][1]
            count(sub, back - idx)
            for back in dp[level][idx][1]:
                node = count(sub, back)
                dp[level + 1][idx] = max(dp[level + 1][idx], node)

    max_a, idx = dp[n][0]
    while max_a < n and idx > -1:
        max_a -= indices[idx][0]
        idx = indices[idx][1]
    if max_a > idx:
        dp[n][0] = (n - 1, n)
    for i in range(n + 1):
        matrix = [set(), set()]
        for s in range(i):
            for nxt in range(s + 1, i):
                if dp[s][i - 1] == i + nxt:
                    matrix[0].add(s)
                    matrix[1].add(nxt)
