                else:
                    z = end_cx - (math.tan(complex_angle(bi, ci)) * (z := slope_denom((end_cx, start_cx), branch - j)))

            ray_cx = get_ray_cx(circle_intersection(circles[-1], circles[i], segments[i]))
            for l in bi:
