from collections import defaultdict, deque

def build_graph(edges):
    neighbors = defaultdict(list)
    for v, u, w in edges:
        neighbors[v].append((u, w))
        neighbors[u].append((v, w))
    return neighbors

def dijkstra(graph, start):
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    visited = set()
    pq = [(0, start)]

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_node in visited:
            continue

        visited.add(current_node)

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return distances

def find_max_weight_subgraph(n, edges, vertex_weights):
    graph = build_graph(edges)
    vertex_weights = vertex_weights + [0] * (n - len(vertex_weights))
    max_weight = -float('inf')

    for i in range(1 << n):
        subset_weights = vertex_weights.copy()
        subset_edges = defaultdict(int)
        subsets = []

        for j in range(n):
            if i & (1 << j):
                subsets.append(j + 1)

        for v, u, w in edges:
            if both in subsets:
                if v in subsets:
                    subset_edges[mapping[v]] += w
                else:
                    subset_edges[mapping[u]] += w

        subgraph_distances = dijkstra(subset_edges, start=0)

        for j in range(n):
            if j in subsets:
                subset_weights[j] -= subgraph_distances[j]
            else:
                subset_weights[j] += subgraph_distances[j]

        max_weight = max(max_weight, sum(subset_weights))

    return max_weight

