import sys

class BipartiteGraph:
    def __init__(self, vertices, edges, colors=4):
        self.vertices = vertices
        self.edges = edges
        self.colors = colors
        self.coloring = [[0] * vertices for _ in range(vertices)]
        self.matching = [[0] * vertices for _ in range(vertices)]

    def bipartite_matching(self):
        for i in range(self.vertices):
            self.matching[i][i] = i
            self.coloring[i][i] = 0

        for i in range(self.vertices):
            mid = bfs(self.matching, i)
            if mid == -1:
                return 0

        return sum(map(lambda x: x != 0, self.bfs_matching()))

    @staticmethod
    def bfs_matching(algo, source):
        nb = algo.__len__()
        visited = [False] * nb
        pred = {i: -1 for i in range(nb)}
        queue = [source]

        while queue:
            node = queue.pop(0)
            visited[node] = True

            for i in range(nb):
                if algo[node][i] > 0 and not visited[i]:
                    pred[i] = node
                    queue.append(i)
                    if i == source:
                        break

        match = [-1] * nb
        node = source
        while node != -1:
            prev = pred[node]
            for i in range(nb):
                if algo[node][i] > 0 and i not in match:
                    match[i] = prev
            node = prev

        return match

def partition(num_parts, edges):
    graph = BipartiteGraph(num_parts)
    for source, target in edges:
        graph.edges[source-1][target-1] = max(0, min(graph.colors, graph.matching[source-1][target-1]))
        graph.matching[source-1][target-1] = max(0, min(graph.colors, graph.matching[target-1][source-1]))
    return graph.bipartite_matching()

