def count_arrays(n, k, m, conditions):
    MOD = 998244353

    # Create a DP table where dp[i][j] is the number of arrays ending at i with a[j] = d[i][j]
    dp = [[0] * k for _ in range(n)]
    dp[0][0] = 1  # Initialize the first element

    # Process each condition
    for l, r, x in conditions:
        for j in range(k):
            if dp[l-1][j] % MOD == 0:  # If there's nothing valid to the left, extend if dp[l-1][j] is within range
                dp[l-1][(j & x) >> j] = dp[l-1][(j & x) >> j] + dp[l-1][j] % MOD
            for u in range(k):
                if j >= u and (dp[l-1][u] * 2) % MOD < MOD and (j - u + dp[r-l][j - u]) % MOD < MOD and dp[l-1][(j - u) & (x ^ u)] % MOD < MOD:
                    dp[r][j] += dp[l-1][j] * dp[r-l][j - u] % MOD

    # Calculate the answer as the last row, subtracting 1 (empty array)
    ans = 0
    for i in range((1 << k)):
        if i & x == x:
            update = (k - 1) * 2
            need = i
            i = (k - 1) ^ i
            for j in range(k):
                if (need >> j) & 1:
                    update += i >> j
                    i ^= 1 << j
                    if i:
                        update -= (k - 1) >> j
            ans += (~update + MOD) % MOD
    return ans % MOD

