        if front_cards[0] < -back_cards[-1]:
            front_cards.append(front_cards.popleft())
            back_cards.appendleft(back_cards.pop())
        else:
            break

    if front_cards[0] != -back_cards[-1]:
        return "NO"

    front_dict[abs(front_cards[0])] = int(front_cards.popleft())
    front_dict[abs(back_cards[-1])] = int(back_cards.popleft())

    res = []
    curr_front = [front_dict[i] for i in sorted(front_dict.keys())]
    curr_back = [front_dict[i] for i in sorted(front_dict.keys())]
    i, j = 0, len(back_cards) - 2
    while i < len(curr_front):
