        res.append(-curr_back[j])
        i += 1
        j -= 1

    for num in front_cards:
        if num != 0:
            res.append(-num)

    for num in back_cards:
        if num != 0:
            res.append(num)

    return "YES" + "\n" + "\n".join(map(str, res))

