from collections import deque

def isValidSequence(front_brackets, back_brackets):
    stack = deque()
    for front in front_brackets:
        if stack and stack[-1] == front:
            stack.pop()
        else:
            stack.append(front)
    for back in back_brackets:
        if stack and back in [-stack[-1], -stack[0]]:
            stack.pop()
        else:
            stack.append(back)
    return not stack

def canBalance(brackets):
