    balanced_fronts, closed_brackets = deque(fronts), deque()

    for front, back in pairs:
        while closed_brackets and closed_brackets[-1] == -back:
            balanced_fronts.popleft()
            closed_brackets.pop()
        balanced_fronts.append(front)
        closed_brackets.append(back)

    for front in balanced_fronts:
        if closed_brackets and closed_brackets[-1] * front < 0:
            return "NO"
    return "YES\n" + "\n".join(map(str, front + back for front, back in pairs))

