import collections

def is_red_blue_tree(adj_list, initial_color, color):
    color_list = [initial_color[i] for i in range(len(adj_list))]
    queue = collections.deque([0])

    while queue:
        u = queue.popleft()
        color_list[u] = color
        for v in adj_list[u]:
            if color != color_list[v]:
                queue.append(v)

    return all([color_list[i] == color for i in range(len(adj_list))])

def min_operations(adj_list, initial_colors, tree_str):
    operations = 0
    root = 0

    for i in range(len(tree_str)):
        if initial_colors[i] == 0:
            if is_red_blue_tree(adj_list, initial_colors, tree_str[:i+1]):
                root = i
                break

    if root == 0:
        return -1

    queue = collections.deque([root])
    visited = [False] * len(adj_list)
    visited[root] = True

    while queue:
        size = len(queue)
        for _ in range(size):
            u = queue.popleft()
            if u == root:
                break
            for v in adj_list[u]:
                if not visited[v]:
                    queue.append(v)
                    visited[v] = True

        operations += 1

    return operations

