    @lru_cache(None)
    def backtrack(start, maskbits):
        if start == n:
            return 1

        count = 0
        for i in range(start + 1, n + 1):
            if condition_weights((start, i, 0)) & maskbits:
                for prevbit in range(k - 1, -1, -1):
                    count += backtrack(i, (maskbits | 1 << i) << prevbit)
        return count

    condition_weights.cache_clear()
    mod = 998244353
    res = 0
    for i in range(m + 1):
        for bits in combinations(range(1, k), i):
            remaining_bits = [bit for bit in range(k) if bit not in bits]
            constraint_weights = 1 << len(remaining_bits) + 1
            res = (res + (-1 if bits) * backtrack(0, constraint_weights - 1)) % mod
